{"cards": [{"node_code": "N_29fd7d35ea3267d9", "definition": "利用电磁力使列车悬浮于轨道上方运行的铁路系统，涵盖常导/超导磁浮技术、悬浮导向系统、直线电机驱动及专用线路设施。", "boundary": "本节点聚焦于“磁浮”这一特定驱动与导向原理。边界在于区分“磁浮”与“轮轨”（磁浮无接触，轮轨有接触）；区分“磁浮”与“普通电气化铁路”（磁浮通常采用直线电机，普通铁路采用旋转电机）。若内容涉及磁浮列车在城市交通中的应用，主挂载本节点；若涉及磁浮原理在工业非交通领域的应用，不作本节点主挂载。", "includes": ["磁浮列车车辆工程、悬浮与导向控制系统", "磁浮专用轨道梁、站台及供电设施", "磁浮铁路的运营技术与安全标准"], "excludes": ["常规轮轨铁路的机车车辆技术", "非交通领域的磁悬浮装置（如磁悬浮轴承）"], "sibling_distinctions": [{"other_code": "N_7ae01733badc4efb", "rule": "区分依据为驱动与导向原理：磁浮铁路依靠电磁力悬浮和导向，无轮轨接触；高速铁路通常指轮轨导向、高速运行的铁路系统。"}, {"other_code": "N_bf7339b59bac14c0", "rule": "区分依据为动力传输方式：磁浮铁路通常由车载直线电机驱动；缆索铁路由外部缆索牵引。"}], "cross_boundary_rule": "若内容涉及“高速磁浮”，主挂载本节点；若内容涉及“轮轨高速”，主挂载高速铁路节点。"}, {"node_code": "N_7ae01733badc4efb", "definition": "指设计运营速度通常超过200km/h的轮轨铁路系统，涵盖高速线路工程、动车组技术、信号控制及高速运营组织与服务。", "boundary": "本节点聚焦于“高速”这一速度等级特征，通常基于轮轨导向。边界在于区分“高速铁路”与“普通铁路”（速度等级不同，线路标准、车辆技术有显著差异）；区分“高速铁路”与“磁浮铁路”（导向方式不同，轮轨vs磁浮）。若内容涉及高速磁浮，归入磁浮铁路；若涉及轮轨高速，归入本节点。", "includes": ["高速铁路线路、桥梁、隧道等基础设施工程", "高速动车组车辆技术、牵引供电及通信信号系统", "高速铁路运营管理、调度指挥及客运服务组织"], "excludes": ["磁浮铁路系统（归入磁浮铁路节点）", "普通速度等级（<200km/h）的轮轨铁路技术"], "sibling_distinctions": [{"other_code": "N_29fd7d35ea3267d9", "rule": "区分依据为导向方式：高速铁路通常指轮轨导向的高速系统；磁浮铁路指磁悬浮导向系统，无论速度高低。"}, {"other_code": "N_1029b5c0c888d021", "rule": "区分依据为速度等级与定位：高速铁路侧重城际或长途高速运输；轻轨铁路通常指城市内部中低速、中小运量轨道交通。"}], "cross_boundary_rule": "若内容明确为“轮轨高速”，主挂载本节点；若为“磁浮高速”，主挂载磁浮铁路节点。"}, {"node_code": "N_bf7339b59bac14c0", "definition": "利用缆索（钢丝绳、链条等）牵引车辆沿固定轨道运行的铁路系统，涵盖索道、架空缆车、地面缆索铁路等类型及其设施。", "boundary": "本节点聚焦于“缆索牵引”这一动力传输方式。边界在于区分“缆索铁路”与“自走式铁路”（缆索铁路车辆通常无自走动力或动力较弱，依赖外部缆索）；区分“缆索铁路”与“索道”（若树中无独立索道节点，客运索道归入本节点或特种铁路其他类，需视具体定义，此处归入缆索铁路）。若内容涉及矿山、景区的缆索运输，主挂载本节点。", "includes": ["缆索铁路的线路、支架、缆索及驱动站设施", "缆索牵引车辆（车厢、吊厢）及控制系统", "缆索铁路的运营安全与维护技术"], "excludes": ["自走式轮轨铁路（如地铁、普通铁路）", "非轨道式的纯空中索道（若树中有独立“索道”节点则归入该节点，否则视同缆索铁路）"], "sibling_distinctions": [{"other_code": "N_29fd7d35ea3267d9", "rule": "区分依据为动力来源：缆索铁路由外部缆索牵引；磁浮铁路由车载电磁驱动。"}, {"other_code": "N_7ae01733badc4efb", "rule": "区分依据为运行速度与动力：缆索铁路通常速度较低，依赖缆索；高速铁路速度高，依赖车载动力。"}], "cross_boundary_rule": "若内容涉及“客运索道”且树中无独立节点，主挂载本节点；若涉及“自走式缆索辅助铁路”，需视主导动力方式，若主要靠缆索则归本节点。"}]}
